/* Margin — Editorial Landing Page Styles */
/* Print-inspired design with typography, rules, whitespace, asymmetric composition */

:root {
    --color-ink: #1a1a1a;
    --color-ink-light: #333333;
    --color-paper: #faf9f6;
    --color-paper-warm: #f5f3ef;
    --color-accent: #c41e3a;
    --color-accent-hover: #a0182f;
    --color-muted: #6b6b6b;
    --color-border: #d8d4cf;
    --color-focus: #2563eb;
    --color-success: #166534;
    --color-error: #b91c1c;

    --font-display: "Georgia", "Cambria", "Times New Roman", serif;
    --font-text: "Georgia", "Cambria", "Times New Roman", serif;
    --font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

    --space-xs: 0.25rem;
    --space-sm: 0.5rem;
    --space-md: 1rem;
    --space-lg: 1.5rem;
    --space-xl: 2.5rem;
    --space-2xl: 4rem;
    --space-3xl: 6rem;

    --measure: 38rem;
    --measure-narrow: 30rem;

    --transition-fast: 120ms ease;
    --transition-normal: 200ms ease;

    --reading-bg: #1e1e1e;
    --reading-text: #e8e6e1;
    --reading-muted: #9a9a9a;
    --reading-border: #3d3d3d;
    --reading-accent: #f5c542;
}

*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    font-size: 100%;
    scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

body {
    font-family: var(--font-text);
    font-size: 1rem;
    line-height: 1.7;
    color: var(--color-ink);
    background: var(--color-paper);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
}

.skip-link {
    position: absolute;
    top: -100%;
    left: 50%;
    transform: translateX(-50%);
    padding: var(--space-sm) var(--space-md);
    font-family: var(--font-ui);
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--color-paper);
    background: var(--color-ink);
    border-radius: 0 0 4px 4px;
    z-index: 1000;
    transition: top var(--transition-fast);
}

.skip-link:focus {
    top: 0;
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Header */
.site-header {
    position: sticky;
    top: 0;
    z-index: 100;
    background: var(--color-paper);
    border-bottom: 1px solid var(--color-border);
}

.header-inner {
    max-width: var(--measure);
    margin: 0 auto;
    padding: var(--space-lg) var(--space-md);
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: var(--space-md);
}

.journal-identity {
    flex: 1;
    min-width: 0;
}

.journal-label {
    display: block;
    font-family: var(--font-ui);
    font-size: 0.6875rem;
    font-weight: 600;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-bottom: var(--space-xs);
}

.journal-title {
    font-family: var(--font-display);
    font-size: clamp(2.5rem, 6vw, 4rem);
    font-weight: 400;
    font-style: italic;
    line-height: 1.1;
    letter-spacing: -0.02em;
    color: var(--color-ink);
}

.journal-tagline {
    display: block;
    font-family: var(--font-ui);
    font-size: 0.75rem;
    font-weight: 400;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-top: var(--space-xs);
}

.header-nav {
    flex-shrink: 0;
}

.reading-mode-toggle {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    padding: var(--space-sm) var(--space-md);
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--color-ink-light);
    background: transparent;
    border: 1px solid var(--color-border);
    border-radius: 4px;
    cursor: pointer;
    transition: all var(--transition-fast);
}

.reading-mode-toggle:hover {
    background: var(--color-paper-warm);
    border-color: var(--color-ink-light);
}

.reading-mode-toggle:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
    border-color: var(--color-focus);
}

.reading-mode-toggle[aria-pressed="true"] {
    background: var(--color-ink);
    color: var(--color-paper);
    border-color: var(--color-ink);
}

.reading-mode-toggle[aria-pressed="true"]:hover {
    background: var(--color-ink-light);
}

.icon-sun {
    display: none;
}

.reading-mode-toggle[aria-pressed="true"] .icon-book {
    display: none;
}

.reading-mode-toggle[aria-pressed="true"] .icon-sun {
    display: block;
}

.header-rule {
    border: none;
    border-top: 1px solid var(--color-border);
    margin: 0 var(--space-md);
}

/* Main */
main {
    max-width: var(--measure);
    margin: 0 auto;
    padding: var(--space-xl) var(--space-md) var(--space-3xl);
}

/* Issue Hero */
.issue-hero {
    text-align: left;
    margin-bottom: var(--space-3xl);
}

.issue-meta {
    display: flex;
    align-items: baseline;
    gap: var(--space-lg);
    margin-bottom: var(--space-md);
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    font-weight: 500;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--color-muted);
}

.issue-number::after {
    content: "";
    display: inline-block;
    width: 40px;
    height: 1px;
    background: var(--color-border);
    margin-left: var(--space-lg);
    vertical-align: middle;
}

.issue-title {
    font-family: var(--font-display);
    font-size: clamp(3rem, 8vw, 5.5rem);
    font-weight: 400;
    font-style: italic;
    line-height: 1.05;
    letter-spacing: -0.03em;
    color: var(--color-ink);
    margin-bottom: var(--space-xs);
}

.issue-subtitle {
    font-family: var(--font-display);
    font-size: clamp(1.125rem, 2.5vw, 1.5rem);
    font-weight: 400;
    font-style: italic;
    line-height: 1.4;
    color: var(--color-ink-light);
    max-width: var(--measure-narrow);
    margin-bottom: var(--space-lg);
}

.hero-rule {
    border: none;
    border-top: 2px solid var(--color-ink);
    width: 60px;
    margin: 0;
}

/* Cover Story */
.cover-story {
    margin-bottom: var(--space-3xl);
    padding-bottom: var(--space-2xl);
}

.story-header {
    margin-bottom: var(--space-lg);
}

.story-category {
    display: inline-block;
    font-family: var(--font-ui);
    font-size: 0.6875rem;
    font-weight: 600;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--color-accent);
    margin-bottom: var(--space-sm);
}

.story-title {
    font-family: var(--font-display);
    font-size: clamp(2rem, 4.5vw, 3rem);
    font-weight: 400;
    font-style: italic;
    line-height: 1.2;
    letter-spacing: -0.02em;
    color: var(--color-ink);
    margin-bottom: var(--space-xs);
}

.story-byline {
    font-family: var(--font-text);
    font-size: 1rem;
    font-style: italic;
    color: var(--color-muted);
}

.story-content {
    max-width: var(--measure-narrow);
}

.story-summary {
    font-size: 1.125rem;
    line-height: 1.8;
    color: var(--color-ink-light);
    margin-bottom: var(--space-lg);
}

.story-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    font-family: var(--font-ui);
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--color-ink);
    text-decoration: none;
    border-bottom: 1px solid var(--color-ink);
    padding-bottom: 2px;
    transition: all var(--transition-fast);
}

.story-link:hover {
    color: var(--color-accent);
    border-color: var(--color-accent);
}

.story-link:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 3px;
    border-radius: 2px;
    border-color: var(--color-focus);
}

.story-link svg {
    flex-shrink: 0;
    transition: transform var(--transition-fast);
}

.story-link:hover svg {
    transform: translateX(4px);
}

.story-rule {
    border: none;
    border-top: 1px solid var(--color-border);
    margin-top: var(--space-xl);
}

/* Supporting Stories */
.supporting-stories {
    margin-bottom: var(--space-3xl);
}

.section-header {
    margin-bottom: var(--space-xl);
}

.section-title {
    font-family: var(--font-display);
    font-size: clamp(1.5rem, 3vw, 2rem);
    font-weight: 400;
    font-style: italic;
    line-height: 1.3;
    color: var(--color-ink);
}

.stories-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-xl);
}

.story-card {
    padding-bottom: var(--space-lg);
    border-bottom: 1px solid var(--color-border);
}

.story-card:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.card-header {
    margin-bottom: var(--space-md);
}

.card-title {
    font-family: var(--font-display);
    font-size: 1.375rem;
    font-weight: 400;
    font-style: italic;
    line-height: 1.3;
    color: var(--color-ink);
    margin-bottom: var(--space-xs);
}

.card-byline {
    font-family: var(--font-text);
    font-size: 0.9375rem;
    font-style: italic;
    color: var(--color-muted);
}

.card-summary {
    font-size: 1rem;
    line-height: 1.75;
    color: var(--color-ink-light);
    margin-bottom: var(--space-md);
}

.card-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--color-ink);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    padding-bottom: 1px;
    transition: all var(--transition-fast);
}

.card-link:hover {
    color: var(--color-accent);
    border-color: var(--color-accent);
}

.card-link:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 3px;
    border-radius: 2px;
    border-color: var(--color-focus);
}

.card-link svg {
    flex-shrink: 0;
    transition: transform var(--transition-fast);
}

.card-link:hover svg {
    transform: translateX(3px);
}

/* Archive Strip */
.archive-strip {
    margin-bottom: var(--space-3xl);
    padding-bottom: var(--space-2xl);
}

.archive-list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-md);
    font-family: var(--font-text);
    font-size: 1rem;
    line-height: 1.6;
}

.archive-item {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    white-space: nowrap;
}

.archive-issue {
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--color-muted);
}

.archive-title {
    font-style: italic;
    color: var(--color-ink);
}

.archive-separator {
    color: var(--color-border);
}

.archive-rule {
    border: none;
    border-top: 1px solid var(--color-border);
    margin-top: var(--space-xl);
}

/* Subscription */
.subscription {
    padding-top: var(--space-xl);
}

.subscription-content {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-xl);
    align-items: start;
}

.offer-text {
    font-family: var(--font-display);
    font-size: clamp(1.25rem, 2.5vw, 1.75rem);
    font-weight: 400;
    font-style: italic;
    line-height: 1.4;
    color: var(--color-ink);
    max-width: var(--measure-narrow);
}

.offer-text strong {
    font-family: var(--font-ui);
    font-weight: 600;
    font-style: normal;
}

.subscription-form {
    width: 100%;
    max-width: 380px;
}

.form-group {
    display: flex;
    gap: var(--space-sm);
}

.email-input {
    flex: 1;
    min-width: 0;
    padding: var(--space-md) var(--space-lg);
    font-family: var(--font-text);
    font-size: 1rem;
    line-height: 1.5;
    color: var(--color-ink);
    background: var(--color-paper);
    border: 1px solid var(--color-border);
    border-radius: 4px;
    transition: all var(--transition-fast);
}

.email-input::placeholder {
    color: var(--color-muted);
    font-style: italic;
}

.email-input:hover {
    border-color: var(--color-ink-light);
}

.email-input:focus {
    outline: none;
    border-color: var(--color-focus);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.email-input:invalid:not(:placeholder-shown) {
    border-color: var(--color-error);
}

.email-input:valid:not(:placeholder-shown) {
    border-color: var(--color-success);
}

.submit-btn {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    padding: 0;
    color: var(--color-paper);
    background: var(--color-ink);
    border: 1px solid var(--color-ink);
    border-radius: 4px;
    cursor: pointer;
    transition: all var(--transition-fast);
}

.submit-btn:hover {
    background: var(--color-ink-light);
    border-color: var(--color-ink-light);
}

.submit-btn:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.submit-btn:active {
    transform: scale(0.98);
}

.form-feedback {
    margin-top: var(--space-sm);
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    line-height: 1.5;
    min-height: 1.25rem;
    transition: opacity var(--transition-fast);
}

.form-feedback.success {
    color: var(--color-success);
}

.form-feedback.error {
    color: var(--color-error);
}

/* Footer */
.site-footer {
    background: var(--color-paper-warm);
    border-top: 1px solid var(--color-border);
    margin-top: var(--space-3xl);
}

.footer-rule {
    border: none;
    border-top: 1px solid var(--color-border);
    max-width: var(--measure);
    margin: 0 auto var(--space-lg);
}

.footer-inner {
    max-width: var(--measure);
    margin: 0 auto;
    padding: var(--space-xl) var(--space-md) var(--space-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--space-md);
    flex-wrap: wrap;
}

.copyright {
    font-family: var(--font-text);
    font-size: 0.875rem;
    font-style: italic;
    color: var(--color-muted);
}

.footer-nav {
    display: flex;
    gap: var(--space-lg);
}

.footer-link {
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--color-ink-light);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    padding-bottom: 1px;
    transition: all var(--transition-fast);
}

.footer-link:hover {
    color: var(--color-accent);
    border-color: var(--color-accent);
}

.footer-link:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 3px;
    border-radius: 2px;
}

/* Reading Mode */
body.reading-mode {
    background: var(--reading-bg);
    color: var(--reading-text);
}

body.reading-mode .site-header,
body.reading-mode .site-footer {
    background: var(--reading-bg);
    border-color: var(--reading-border);
}

body.reading-mode .journal-title,
body.reading-mode .issue-title,
body.reading-mode .story-title,
body.reading-mode .card-title,
body.reading-mode .archive-title,
body.reading-mode .section-title,
body.reading-mode .subscribe-title,
body.reading-mode .offer-text,
body.reading-mode .story-summary,
body.reading-mode .card-summary,
body.reading-mode .archive-title,
body.reading-mode .copyright {
    color: var(--reading-text);
}

body.reading-mode .journal-label,
body.reading-mode .journal-tagline,
body.reading-mode .issue-number,
body.reading-mode .issue-date,
body.reading-mode .story-byline,
body.reading-mode .card-byline,
body.reading-mode .archive-issue,
body.reading-mode .footer-link {
    color: var(--reading-muted);
}

body.reading-mode .story-category {
    color: var(--reading-accent);
}

body.reading-mode .story-link,
body.reading-mode .card-link,
body.reading-mode .footer-link {
    color: var(--reading-text);
    border-color: var(--reading-text);
}

body.reading-mode .story-link:hover,
body.reading-mode .card-link:hover,
body.reading-mode .footer-link:hover {
    color: var(--reading-accent);
    border-color: var(--reading-accent);
}

body.reading-mode .hero-rule {
    border-color: var(--reading-text);
}

body.reading-mode .story-rule,
body.reading-mode .archive-rule,
body.reading-mode .footer-rule,
body.reading-mode .header-rule,
body.reading-mode .story-card {
    border-color: var(--reading-border);
}

body.reading-mode .archive-separator {
    color: var(--reading-border);
}

body.reading-mode .email-input {
    background: #2a2a2a;
    border-color: var(--reading-border);
    color: var(--reading-text);
}

body.reading-mode .email-input::placeholder {
    color: var(--reading-muted);
}

body.reading-mode .email-input:focus {
    border-color: var(--reading-accent);
    box-shadow: 0 0 0 3px rgba(245, 197, 66, 0.15);
}

body.reading-mode .submit-btn {
    background: var(--reading-text);
    border-color: var(--reading-text);
    color: var(--reading-bg);
}

body.reading-mode .submit-btn:hover {
    background: var(--reading-accent);
    border-color: var(--reading-accent);
}

body.reading-mode .reading-mode-toggle {
    background: var(--reading-bg);
    border-color: var(--reading-border);
    color: var(--reading-text);
}

body.reading-mode .reading-mode-toggle:hover {
    background: #2a2a2a;
}

body.reading-mode .reading-mode-toggle[aria-pressed="true"] {
    background: var(--reading-accent);
    border-color: var(--reading-accent);
    color: var(--reading-bg);
}

/* Responsive: Tablet and up */
@media (min-width: 560px) {
    .header-inner {
        padding: var(--space-xl) var(--space-lg);
    }

    main {
        padding: var(--space-2xl) var(--space-lg) var(--space-3xl);
    }

    .issue-hero {
        margin-bottom: var(--space-3xl);
    }

    .stories-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .story-card:nth-child(3) {
        grid-column: span 2;
        max-width: var(--measure-narrow);
    }

    .subscription-content {
        grid-template-columns: 1fr auto;
        align-items: center;
    }

    .footer-inner {
        padding: var(--space-xl) var(--space-lg) var(--space-lg);
    }
}

/* Responsive: Desktop */
@media (min-width: 900px) {
    :root {
        --space-xl: 3rem;
        --space-2xl: 5rem;
        --space-3xl: 8rem;
    }

    .header-inner {
        padding: var(--space-xl) var(--space-xl);
    }

    main {
        padding: var(--space-2xl) var(--space-xl) var(--space-3xl);
    }

    .journal-title {
        font-size: 3.5rem;
    }

    .issue-title {
        font-size: 5rem;
    }

    .issue-meta {
        font-size: 0.875rem;
    }

    .stories-grid {
        grid-template-columns: repeat(3, 1fr);
    }

    .story-card:nth-child(3) {
        grid-column: auto;
        max-width: none;
    }

    .archive-list {
        gap: var(--space-xl);
    }

    .subscription-content {
        grid-template-columns: 1fr 420px;
    }

    .footer-inner {
        padding: var(--space-xl) var(--space-xl) var(--space-lg);
    }
}

/* Large Desktop */
@media (min-width: 1200px) {
    .issue-hero {
        display: grid;
